def string_expansion(input_string):
    result = []
    i = 0
    while i < len(input_string):
        char = input_string[i]
        if i + 1 < len(input_string) and input_string[i + 1].isdigit():
            count = int(input_string[i + 1])
            result.append(char * count)
            i += 2
        else:
            result.append(char)
            i += 1
    return ''.join(result)
